S.append(story("die_party_bei_kai", "A2-1", "Die Party bei Kai",
 ("Mia đến dự tiệc ở nhà Kai, nơi cô gần như không quen ai. Rồi cô gặp Tom.", "Mia goes to a party at Kai's, where she hardly knows anyone. Then she meets Tom."),
 ["Papier", "Stimmung", "fröhlich"],
 [("N", "Kai macht am Samstag eine Party in seiner Wohnung.", "Thứ Bảy Kai tổ chức tiệc ở căn hộ của mình.", "Kai is having a party in his flat on Saturday."),
  ("N", "Er lädt viele Leute ein: Freunde, Kollegen und Nachbarn.", "Anh mời rất nhiều người: bạn bè, đồng nghiệp và hàng xóm.", "He invites lots of people: friends, colleagues and neighbours."),
  ("N", "Mia kennt dort nur Kai.", "Ở đó Mia chỉ quen mỗi Kai.", "Mia only knows Kai there."),
  ("B", "Ich habe ein bisschen Angst.", "Mình hơi sợ.", "I'm a bit nervous."),
  ("A", "Keine Angst! Die Leute sind alle nett.", "Đừng lo! Mọi người đều dễ mến cả.", "Don't worry! The people are all nice."),
  ("N", "Die Stimmung ist super. Alle sind fröhlich.", "Không khí tuyệt vời. Ai cũng vui vẻ.", "The atmosphere is great. Everyone is cheerful."),
  ("N", "In der Küche steht ein großer Typ mit schwarzen Haaren.", "Trong bếp có một anh chàng cao lớn tóc đen.", "In the kitchen there is a tall guy with black hair."),
  ("N", "Er erzählt lustige Geschichten, und alle lachen.", "Anh ta kể những câu chuyện vui, và mọi người đều cười.", "He tells funny stories, and everyone laughs."),
  ("B", "Wer ist das?", "Ai vậy?", "Who is that?"),
  ("A", "Das ist Tom, ein Kumpel von mir. Er ist ein bisschen komisch, aber cool.", "Đó là Tom, bạn mình. Cậu ấy hơi lạ, nhưng ngầu lắm.", "That's Tom, a mate of mine. He's a bit odd, but cool."),
  ("N", "Dann kommt Tom zu Mia.", "Rồi Tom đến chỗ Mia.", "Then Tom comes over to Mia."),
  ("A", "Hallo! Ich bin Tom. Und wer bist du?", "Chào! Mình là Tom. Còn cậu là ai?", "Hi! I'm Tom. And who are you?"),
  ("B", "Ich bin Mia. Ich arbeite mit Kai zusammen.", "Mình là Mia. Mình làm cùng chỗ với Kai.", "I'm Mia. I work with Kai."),
  ("N", "Sie reden lange über Musik, Filme und Reisen.", "Hai người nói chuyện rất lâu về âm nhạc, phim ảnh và du lịch.", "They talk for a long time about music, films and travelling."),
  ("N", "Dann spielt jemand ein Lied, und Tom fragt: Tanzt du mit mir?", "Rồi có người bật một bài hát, và Tom hỏi: Cậu nhảy với mình nhé?", "Then someone plays a song, and Tom asks: Will you dance with me?"),
  ("B", "Ich tanze sehr schlecht!", "Mình nhảy dở lắm!", "I dance really badly!"),
  ("A", "Kein Problem. Hier geht es nur um den Spaß!", "Không sao. Ở đây chỉ cần vui thôi!", "No problem. Here it's just about having fun!"),
  ("N", "Sie tanzen, und Mia hat sehr viel Spaß.", "Họ nhảy, và Mia rất vui.", "They dance, and Mia has a lot of fun."),
  ("N", "Sehr spät sagt Mia: Ich muss jetzt gehen.", "Rất khuya Mia nói: Mình phải về rồi.", "Very late Mia says: I have to go now."),
  ("A", "Gibst du mir deine Nummer?", "Cậu cho mình số điện thoại nhé?", "Will you give me your number?"),
  ("N", "Mia lacht und schreibt ihre Nummer auf ein Stück Papier.", "Mia cười và viết số điện thoại lên một mẩu giấy.", "Mia laughs and writes her number on a piece of paper."),
  ("N", "Am nächsten Tag kriegt sie eine Nachricht: Wann tanzen wir wieder?", "Hôm sau cô nhận được tin nhắn: Khi nào bọn mình lại nhảy nữa?", "The next day she gets a message: When are we dancing again?"),
  ("N", "Mia ist eigentlich noch müde, aber sie antwortet sofort.", "Thật ra Mia vẫn còn mệt, nhưng cô trả lời ngay.", "Mia is actually still tired, but she answers straight away.")],
 [("locate", "Ai kể những câu chuyện vui trong bếp?", "Who tells funny stories in the kitchen?", [("Kai", "Kai"), ("Tom", "Tom"), ("Một người hàng xóm", "A neighbour")], 1),
  ("locate", "Mia viết số điện thoại lên gì?", "What does Mia write her number on?", [("Một mẩu giấy", "A piece of paper"), ("Điện thoại của Tom", "Tom's phone"), ("Tay của Tom", "Tom's hand")], 0),
  ("infer", "Vì sao lúc đầu Mia hơi sợ?", "Why is Mia a bit nervous at first?", [("Cô không thích tiệc tùng", "She doesn't like parties"), ("Cô nhảy dở", "She dances badly"), ("Ở đó cô chỉ quen mỗi Kai", "She only knows Kai there")], 2)],
 names=["Kai", "Mia", "Tom"]))

S.append(story("hilfe_im_zug", "A2-1", "Hilfe im Zug",
 ("Trên chuyến tàu đông người, ông Nowak giúp một người mẹ trẻ đi cùng em bé. Hôm đó ông đi làm muộn — nhưng rất vui.", "On a crowded train Mr Nowak helps a young mother with her baby. He is late for work that day — but very happy."),
 ["Kilo", "Reihe", "Linie"],
 [("N", "Herr Nowak fährt jeden Morgen mit dem Zug zur Arbeit.", "Sáng nào ông Nowak cũng đi tàu đến chỗ làm.", "Every morning Mr Nowak takes the train to work."),
  ("N", "Heute ist der Zug sehr voll.", "Hôm nay tàu rất đông.", "Today the train is very full."),
  ("N", "An der Tür steht eine junge Frau mit einem Baby und zwei großen Taschen.", "Ở cửa có một phụ nữ trẻ bế em bé và mang hai chiếc túi lớn.", "At the door there is a young woman with a baby and two big bags."),
  ("N", "Die Taschen haben bestimmt zwanzig Kilo. Sie sieht sehr müde aus.", "Mấy chiếc túi chắc phải nặng hai mươi ký. Trông cô rất mệt.", "The bags must weigh twenty kilos. She looks very tired."),
  ("A", "Entschuldigung, möchten Sie sich setzen? In der ersten Reihe ist ein Platz frei.", "Xin lỗi, chị có muốn ngồi không? Ở hàng đầu có một chỗ trống.", "Excuse me, would you like to sit down? There is a free seat in the first row."),
  ("B", "Oh, das ist sehr lieb von Ihnen. Danke!", "Ôi, ông thật tốt bụng. Cảm ơn ông!", "Oh, that's very kind of you. Thank you!"),
  ("N", "Herr Nowak hilft ihr mit den Taschen.", "Ông Nowak giúp cô mang túi.", "Mr Nowak helps her with the bags."),
  ("N", "Das Baby weint laut.", "Em bé khóc to.", "The baby is crying loudly."),
  ("B", "Es tut mir leid. Er hat Hunger, und ich habe die Milch vergessen.", "Tôi xin lỗi. Cháu đói, mà tôi lại quên mang sữa.", "I'm sorry. He's hungry, and I forgot the milk."),
  ("N", "Herr Nowak denkt kurz nach.", "Ông Nowak suy nghĩ một chút.", "Mr Nowak thinks for a moment."),
  ("A", "Am nächsten Bahnhof gibt es ein Café. Der Zug wartet dort fünf Minuten.", "Ở ga tới có một quán cà phê. Tàu dừng ở đó năm phút.", "At the next station there is a café. The train waits there for five minutes."),
  ("N", "Der Zug hält. Herr Nowak läuft schnell zum Café und kauft eine Flasche Milch.", "Tàu dừng lại. Ông Nowak chạy nhanh đến quán và mua một chai sữa.", "The train stops. Mr Nowak runs to the café and buys a bottle of milk."),
  ("N", "Nach vier Minuten ist er wieder im Zug.", "Sau bốn phút ông đã trở lại tàu.", "After four minutes he is back on the train."),
  ("B", "Das ist wirklich wunderbar! Wie kann ich Ihnen danken?", "Thật tuyệt quá! Tôi biết cảm ơn ông thế nào đây?", "That's really wonderful! How can I thank you?"),
  ("A", "Das ist doch nichts. Ich habe auch Kinder.", "Có gì đâu. Tôi cũng có con nhỏ mà.", "It's nothing. I have children too."),
  ("N", "Das Baby trinkt und wird ruhig. Dann schläft es ein.", "Em bé uống sữa và nín dần. Rồi bé ngủ thiếp đi.", "The baby drinks and calms down. Then it falls asleep."),
  ("N", "Die Frau erzählt: Sie kommt aus Vietnam und lebt seit einem Jahr in Deutschland.", "Người phụ nữ kể: cô đến từ Việt Nam và đã sống ở Đức được một năm.", "The woman tells him: she is from Vietnam and has lived in Germany for a year."),
  ("B", "Ich fahre heute zu meiner Schwester nach Bonn.", "Hôm nay tôi đi thăm chị gái ở Bonn.", "Today I'm going to my sister's in Bonn."),
  ("A", "Dann müssen Sie in Köln aussteigen. Die Linie nach Bonn fährt von Gleis acht.", "Vậy chị phải xuống ở Köln. Tuyến đi Bonn chạy từ đường ray số tám.", "Then you have to get off in Cologne. The line to Bonn leaves from platform eight."),
  ("N", "In Köln steigen beide aus, und Herr Nowak bringt sie zum Gleis.", "Đến Köln cả hai cùng xuống, và ông Nowak đưa cô ra đường ray.", "In Cologne they both get off, and Mr Nowak takes her to the platform."),
  ("B", "Vielen Dank für alles! Sie haben mir sehr geholfen.", "Cảm ơn ông về tất cả! Ông đã giúp tôi rất nhiều.", "Thank you for everything! You've helped me a lot."),
  ("N", "An diesem Tag kommt Herr Nowak zu spät zur Arbeit. Aber er ist sehr froh.", "Hôm đó ông Nowak đến chỗ làm muộn. Nhưng ông rất vui.", "That day Mr Nowak is late for work. But he is very happy.")],
 [("locate", "Người mẹ quên mang gì?", "What did the mother forget?", [("Sữa", "Milk"), ("Vé tàu", "Her ticket"), ("Điện thoại", "Her phone")], 0),
  ("locate", "Tuyến đi Bonn chạy từ đường ray số mấy?", "Which platform does the line to Bonn leave from?", [("Số bốn", "Four"), ("Số năm", "Five"), ("Số tám", "Eight")], 2),
  ("infer", "Vì sao hôm đó ông Nowak đi làm muộn?", "Why is Mr Nowak late for work that day?", [("Tàu bị hỏng", "The train broke down"), ("Ông xuống ở Köln để đưa người phụ nữ ra đường ray", "He got off in Cologne to take the woman to her platform"), ("Ông ngủ quên trên tàu", "He fell asleep on the train")], 1)],
 names=["Nowak", "Vietnam", "Deutschland", "Bonn", "Köln"], token_map={"steigen": "aussteigen"}))

S.append(story("der_professor_und_der_stein", "A2-1", "Der Professor und der Stein",
 ("Giáo sư Lang tìm kiếm một hòn đá huyền thoại suốt hai mươi năm. Cô học trò Nora tìm ra nó — vào ngày cuối cùng.", "Professor Lang has been looking for a legendary stone for twenty years. His student Nora finds it — on the very last day."),
 ["Sommer", "regnen", "Kreis"],
 [("N", "Professor Lang arbeitet in einem Museum.", "Giáo sư Lang làm việc trong một viện bảo tàng.", "Professor Lang works in a museum."),
  ("N", "Er sucht seit vielen Jahren einen ganz besonderen Stein.", "Đã nhiều năm ông tìm kiếm một hòn đá rất đặc biệt.", "For many years he has been looking for a very special stone."),
  ("N", "Ein alter Text erzählt: Der Stein liegt in einem Wald, weit von der Stadt.", "Một văn bản cổ kể rằng: hòn đá nằm trong một khu rừng, cách xa thành phố.", "An old text says: the stone lies in a forest, far from the town."),
  ("N", "Auf dem Stein ist ein Zeichen.", "Trên hòn đá có một ký hiệu.", "There is a sign on the stone."),
  ("N", "Viele Leute glauben, die Geschichte ist nicht wahr.", "Nhiều người cho rằng câu chuyện đó không có thật.", "Many people think the story isn't true."),
  ("A", "Ich glaube daran. Den Stein gibt es wirklich!", "Tôi tin vào điều đó. Hòn đá có thật!", "I believe in it. The stone really exists!"),
  ("N", "Das sagt der Professor zu seiner Studentin Nora.", "Giáo sư nói như vậy với cô học trò Nora.", "The professor says that to his student Nora."),
  ("N", "Im Sommer fahren sie zusammen in den Wald.", "Mùa hè hai thầy trò cùng nhau vào rừng.", "In summer they go to the forest together."),
  ("N", "Sie suchen jeden Tag, vom Morgen bis zum Abend.", "Ngày nào họ cũng tìm, từ sáng đến tối.", "They search every day, from morning till evening."),
  ("N", "Sie finden viele Steine, aber keinen mit einem Zeichen.", "Họ tìm thấy nhiều hòn đá, nhưng không hòn nào có ký hiệu.", "They find lots of stones, but none with a sign."),
  ("B", "Herr Professor, vielleicht gibt es den Stein gar nicht.", "Thưa giáo sư, có lẽ hòn đá ấy không hề tồn tại.", "Professor, maybe the stone doesn't exist at all."),
  ("A", "Noch eine Woche. Dann fahren wir nach Hause.", "Thêm một tuần nữa. Rồi chúng ta về nhà.", "One more week. Then we go home."),
  ("N", "Am letzten Tag regnet es sehr stark.", "Vào ngày cuối cùng trời mưa rất to.", "On the last day it rains very hard."),
  ("N", "Nora läuft unter einen großen Baum.", "Nora chạy vào trú dưới một gốc cây to.", "Nora runs under a big tree."),
  ("N", "Da sieht sie unten am Boden etwas Rotes.", "Lúc đó cô thấy dưới đất có một vật màu đỏ.", "There she sees something red down on the ground."),
  ("N", "Es ist ein kleiner, roter Stein. Auf dem Stein ist ein Zeichen: ein Kreis.", "Đó là một hòn đá nhỏ màu đỏ. Trên hòn đá có một ký hiệu: một vòng tròn.", "It is a small red stone. On the stone there is a sign: a circle."),
  ("B", "Herr Professor! Kommen Sie schnell!", "Thưa giáo sư! Thầy đến đây nhanh lên!", "Professor! Come quickly!"),
  ("N", "Der Professor kommt und schaut den Stein lange an.", "Giáo sư đến và nhìn hòn đá rất lâu.", "The professor comes and looks at the stone for a long time."),
  ("N", "Dann misst er ihn genau.", "Rồi ông đo nó thật kỹ.", "Then he measures it carefully."),
  ("A", "Das ist er! Nach zwanzig Jahren!", "Chính là nó! Sau hai mươi năm!", "That's it! After twenty years!"),
  ("N", "Der Professor ist so froh, dass er weint.", "Giáo sư vui đến bật khóc.", "The professor is so happy that he cries."),
  ("A", "Nora, ohne Sie hätte ich ihn nie gefunden.", "Nora, không có cô thì tôi sẽ không bao giờ tìm thấy nó.", "Nora, without you I would never have found it."),
  ("N", "Heute liegt der Stein im Museum. Neben ihm steht: Gefunden von Nora Klein.", "Ngày nay hòn đá nằm trong viện bảo tàng. Bên cạnh có dòng chữ: Do Nora Klein tìm thấy.", "Today the stone is in the museum. Next to it is written: Found by Nora Klein.")],
 [("locate", "Trên hòn đá có ký hiệu gì?", "What sign is on the stone?", [("Một ngôi sao", "A star"), ("Một vòng tròn", "A circle"), ("Một cây thánh giá", "A cross")], 1),
  ("locate", "Ai tìm thấy hòn đá?", "Who finds the stone?", [("Nora", "Nora"), ("Giáo sư Lang", "Professor Lang"), ("Một người trong làng", "Someone from the village")], 0),
  ("infer", "Vì sao Nora tìm thấy hòn đá vào ngày cuối?", "Why does Nora find the stone on the last day?", [("Giáo sư chỉ cho cô chỗ đó", "The professor showed her the place"), ("Cô đọc lại văn bản cổ", "She reread the old text"), ("Trời mưa nên cô chạy vào gốc cây và thấy nó dưới đất", "It rained, so she ran under the tree and saw it on the ground")], 2)],
 names=["Lang", "Nora", "Klein"], token_map={"studentin": "Student", "besonderen": "besonders"}))

